				createdAt: entry.createdAt,
				weight: entry.source === "explicit" ? 0.25 : 0.1,
				note: entry.evidence,
			})),
			...quizResults
				.filter((result) => result.totalQuestions > 0 || (result.openEndedGrades?.length…7460 tokens truncated… => ({
				id: b.id,
				label: `Benchmark: ${b.topic || "general"} (${b.score.toFixed(2)})`,
				type: "benchmark",
				createdAt: b.createdAt,
			})),
			...evolutions.map((e) => ({
				id: e.id,
				label: `Evolution: ${e.topic || "general"} (${e.bestScore.toFixed(2)})`,
				type: "evolution",
